/bin/bash -lc "python3 - <<'PY'
import urllib.request
base='https://raw.githubusercontent.com/NVIDIA/cuda-samples/db3eea23946bca2e90a75eca2b5b3e07158a9e11/Samples/5_Domain_Specific/MonteCarloMultiGPU/'
for name in ['MonteCarloMultiGPU.cpp','MonteCarlo_kernel.cu','CMakeLists.txt']:
    try:
        s=urllib.request.urlopen(base+name,timeout=20).read().decode()
        print(name)
        if name.endswith('.cpp'):
            for a,b in [(57,85),(147,194),(269,327),(426,442),(479,488)]:
                print('\\n'.join(f'{i}: {l}' for i,l in enumerate(s.splitlines(),1) if a<=i<=b))
        elif name.endswith('.cu'):
            for a,b in [(49,80),(125,140),(190,245)]:
                print('\\n'.join(f'{i}: {l}' for i,l in enumerate(s.splitlines(),1) if a<=i<=b))
        else: print(s)
    except Exception as e: print(type(e).__name__,str(e))
PY"

